mapper.select:
SELECT k.kanban_code, w.warehouse_name, sl.location_name, (k.board_qty - COALESCE(k.picked_qty, 0)) AS available_qty, k.received_at FROM kanban_board k JOIN inbound_order_line iol ON iol.id = k.inbound_order_line_id JOIN storage_location sl ON sl.id = k.location_id JOIN warehouse w ON w.id = sl.warehouse_id WHERE k.status = 'RECEIVED' AND (k.board_qty - COALESCE(k.picked_qty, 0)) > 0 AND iol.material_id = #{materialId} AND sl.warehouse_id IN
#{id}
ORDER BY k.received_at ASC, k.id ASC
